evaluate async () => {
  const queries = [
    'prompt+optimizer',
    'prompt+enhancer',
    'prompt+improvement+LLM',
    'prompt+rewrite+AI',
    'prompt+engineering+tool',
    'automatic+prompt+optimization'
  ];

  let allResults = [];

  for (const q of queries) {
    try {
      const resp = await fetch(`https://api.github.com/search/repositories?q=${q}&sort=stars&order=desc&per_page=15`);
      const data = await resp.json();
      if (data.items) {
        data.items.forEach(item => {
          allResults.push({
            name: item.full_name,
            stars: item.stargazers_count,
            desc: (item.description || '').substring(0, 120),
            lang: item.language || 'N/A',
            url: item.html_url
          });
        });
      }
    } catch(e) {
      // skip
    }
  }

  // 去重
  const seen = new Set();
  allResults = allResults.filter(r => {
    if (seen.has(r.name)) return false;
    seen.add(r.name);
    return true;
  });

  // 按 stars 排序
  allResults.sort((a, b) => b.stars - a.stars);

  return JSON.stringify(allResults.slice(0, 60), null, 2);
}

